mapper.insert:
/*LGUTLC00010.createAccessLog*/

		INSERT INTO LGCOM_SYSTEM_ACCESS_LOGGING_N
		     ( EXECUTION_YYYYMM
			 , LOGIN_SERIAL_NO
			 , APPLICATION_USER_ID
			 , MENU_ID
			 , ACCESS_DATE
			 , LOGIN_IP_ADDR
			 , CREATED_BY
			 , CREATION_DATE
			 , LAST_UPDATED_BY
			 , LAST_UPDATE_DATE )
		VALUES
			(  TO_CHAR(SYSDATE,'YYYYMM')
			 , LGCOM_SYSTEM_ACC_LOGGING_N_SEQ.NEXTVAL
			 , #{applicationUserId}
			 , #{menuId}
			 , #{accessDate}
			 , #{loginIpAddr}
			 , #{createdBy}
			 , SYSDATE
			 , #{lastUpdatedBy}
			 , SYSDATE )

/*LGUTLC00010.createServiceTimeLog*/

		INSERT INTO LGCOM_SYSTEM_SERVICE_LOGGING_N
		     ( EXECUTION_YYYYMM
			 , LOG_SEQ_NO
			 , APPLICATION_USER_ID
			 , MENU_ID
			 , PROGRAM_ID
			 , SYSTEM_SERVICE_DESC
			 , ACTUAL_START_TIMESTAMP
			 , ACTUAL_END_TIMESTAMP
			 , CREATED_BY
			 , CREATION_DATE
			 , LAST_UPDATED_BY
			 , LAST_UPDATE_DATE )
		VALUES
			(  TO_CHAR(SYSDATE,'YYYYMM')
			 , LGCOM_SYSTEM_SVC_LOGGING_N_SEQ.NEXTVAL
			 , #{applicationUserId}
			 , #{menuId}
			 , #{programId}
			 , #{systemServiceDesc}
			 , #{actualStartTimestamp}
			 , #{actualEndTimestamp}
			 , #{createdBy}
			 , SYSDATE
			 , #{lastUpdatedBy}
			 , SYSDATE )
